function categoryIcon(category) {
  const art = CATEGORY_ART[category];
  if (!art) return '';
  return '<svg class="category-icon" viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round">'+art.mark+'</g></svg>';
}
function crest(id) {
  const art = TRAIT_ART[id], family = traitGroup(id), category = CATEGORY_ART[family];
  if (!art || !category) throw new Error('Missing trait artwork: '+id);
  return '<svg class="crest" viewBox="0 0 112 112" aria-hidden="true" data-symbol="'+art.symbol+'" data-family="'+family+'"><g class="crest-frame" fill="none" stroke="currentColor" stroke-width="1.05" stroke-linecap="round" stroke-linejoin="round">'+category.frame+'</g><g class="crest-symbol" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+art.body+'</g></svg>';
}

function deltaHtml(m){return '<span class="movement '+escapeText(m.direction)+'" title="'+escapeText(m.label)+'">'+escapeText(m.label)+'</span>';}
function switchView(name){const reports=name==='reports';$('deck-view').classList.toggle('hidden',reports);$('reports-view').classList.toggle('hidden',!reports);$('deck-nav').classList.toggle('active',!reports);$('reports-nav').classList.toggle('active',reports);$('deck-nav').setAttribute('aria-current',reports?'false':'page');$('reports-nav').setAttribute('aria-current',reports?'page':'false');$('page-title').textContent=reports?'Your report archive.':'Your progress deck.';$('page-intro').textContent=reports?'Every run, kept as it was. See what changed, and what stayed the same.':'Every trait has a name. Every number has a sample. Every run leaves a record.';}
function renderFilters(){const groups=['All',...Object.keys(data.groups)];$('filters').innerHTML=groups.map(g=>'<button class="filter '+(group===g?'selected':'')+'" aria-pressed="'+(group===g)+'" data-group="'+escapeText(g)+'">'+categoryIcon(g)+escapeText(g)+'</button>').join('');}
function render(){const view=current.scopes[scope],totals=view.cumulative,changes=current.comparison[scope];
 countUp($('task-count'),totals.episodes);countUp($('chat-count'),totals.sessions);countUp($('measured-count'),Object.values(totals.traits).filter(c=>rate(c)!==null).length);countUp($('saved-count'),data.reports.length);
 const up=Object.values(changes.traits).filter(m=>m.direction==='up').length,down=Object.values(changes.traits).filter(m=>m.direction==='down').length,newly=Object.values(changes.traits).filter(m=>m.direction==='newly-measured').length;
 $('change-summary').textContent=up||down||newly?up+' traits ↑ · '+down+' traits ↓ · '+newly+' newly measured':'No rate changes since the previous saved report.';
 const base=(current.compared_with||{})[scope],previous=base||data.reports.find(r=>r.id===current.previous_id);$('comparison-period').textContent=previous?'Compared with '+formatDate(previous.generated_at)+(base&&base.id!==current.previous_id?' · last report with different counts':''):'First snapshot · comparison begins next run';
 const traits=data.rubric.filter(t=>(group==='All'||traitGroup(t.id)===group)&&(!query||(t.name+' '+t.id+' '+t.definition).toLowerCase().includes(query)));
 $('deck').innerHTML=traits.length?traits.map(t=>{const c=totals.traits[t.id],m=changes.traits[t.id],value=rate(c),denominator=c.eligible-c.declined;return '<button class="trait-card '+(value===null?'unmeasured':'')+'" data-trait="'+t.id+'" aria-label="Open '+escapeText(t.name)+'"><span class="card-top"><span>'+t.id+' / TRAIT</span><span>'+escapeText(traitGroup(t.id))+'</span></span>'+crest(t.id)+'<h3 class="trait-name">'+escapeText(t.name)+'</h3><span class="card-score"><span class="score">'+(value===null?'—':(value*100).toFixed(1)+'<small>%</small>')+'</span>'+deltaHtml(m)+'</span><span class="card-evidence">'+(value===null?(c.eligible<3?c.eligible+' eligible opportunities · 3 needed to measure':'No non-declined opportunities'):c.applied+' applied / '+denominator+' non-declined opportunities')+'</span><span class="card-bottom"><span>'+c.verified_outcome+' VERIFIED</span><span>'+c.unobserved+' UNKNOWN</span></span></button>';}).join(''):'<p class="empty">No traits match this view. Try another name or category.</p>';
 const weeks=Object.entries(totals.weekly).sort((a,b)=>a[0].localeCompare(b[0])).slice(-16),max=Math.max(1,...weeks.map(x=>x[1]));$('weekly-bars').innerHTML=weeks.map(([week,n])=>'<div class="week-bar" style="height:'+Math.max(3,n/max*100)+'%" title="Week '+escapeText(week)+': '+n+' tasks"></div>').join('');$('weekly-bars').setAttribute('aria-label',weeks.length?'Reviewed tasks per week: '+weeks.map(([w,n])=>w+', '+n).join('; '):'No reviewed weekly activity in this cohort');$('week-first').textContent=weeks[0]?.[0]||'No activity';$('week-last').textContent=weeks.at(-1)?.[0]||'';$('weekly-table').innerHTML=weeks.map(([w,n])=>'<tr><td>'+escapeText(w)+'</td><td>'+n+'</td></tr>').join('');
}
function calendarWeeks(rows){const keys=Object.keys(rows).sort();if(!keys.length)return [];const weeks=[];let day=new Date(keys[0]+'T00:00:00Z'),end=new Date(keys.at(-1)+'T00:00:00Z');while(day<=end){const key=day.toISOString().slice(0,10);weeks.push([key,rows[key]??null]);day.setUTCDate(day.getUTCDate()+7);}return weeks;}
function weeklyChart(tid){const weeks=calendarWeeks(current.scopes[scope].cumulative.weekly_traits);const points=weeks.map(([week,rows],i)=>({week,x:12+i/Math.max(1,weeks.length-1)*596,value:rows?rate(rows[tid]):null}));let paths=[],segment=[];for(const p of points){if(p.value===null){if(segment.length)paths.push(segment);segment=[];}else segment.push(p);}if(segment.length)paths.push(segment);if(!paths.length)return '<p class="fine">No week has three comparable opportunities yet.</p>';return '<svg class="week-chart" viewBox="0 0 620 100" role="img" aria-label="Weekly applied rate; gaps are unmeasured"><path d="M12 50H608" stroke="var(--line)" fill="none" stroke-dasharray="3 4"/>'+paths.map(s=>'<polyline points="'+s.map(p=>p.x+','+(88-p.value*76)).join(' ')+'" fill="none" stroke="var(--red)" stroke-width="1.8"/>'+s.map(p=>'<circle cx="'+p.x+'" cy="'+(88-p.value*76)+'" r="2.6" fill="var(--red)"><title>'+escapeText(p.week)+': '+(p.value*100).toFixed(1)+'%</title></circle>').join('')).join('')+'</svg><p class="fine">Each point is one measured week. Missing evidence stays a gap.</p>';}
function openTrait(id){const t=data.rubric.find(x=>x.id===id),view=current.scopes[scope],c=view.cumulative.traits[id],m=current.comparison[scope].traits[id];$('trait-dialog-label').textContent=id+' / '+traitGroup(id)+' / '+data.scope_names[scope];$('trait-dialog-body').innerHTML='<div class="detail-hero">'+crest(id)+'<div><h2 id="trait-dialog-title">'+escapeText(t.name)+'</h2><p>'+escapeText(t.definition.charAt(0).toUpperCase()+t.definition.slice(1))+'</p></div></div><div class="detail-stats"><div><b>'+rateLabel(c)+'</b><span>Applied rate</span></div><div><b>'+c.applied+' / '+(c.eligible-c.declined)+'</b><span>Applied / non-declined</span></div><div><b>'+c.verified_outcome+'</b><span>Verified outcomes</span></div><div><b>'+c.unobserved+'</b><span>Unobserved</span></div></div><p>'+deltaHtml(m)+'</p><p class="fine">Eligible when: '+escapeText(t.eligible_when)+'.</p><div class="legend"><span>'+c.eligible+' eligible</span><span>'+c.applied+' applied</span><span>'+c.missed+' missed</span><span>'+c.declined+' deliberately declined</span></div><h3 class="detail-section-title">Indicators behind this trait</h3><div class="table-scroll"><table><thead><tr><th>Indicator</th><th>Applied rate</th><th>Change</th><th>Verified</th><th>Unknown</th></tr></thead><tbody>'+t.indicators.map(key=>{const row=view.cumulative.indicators[key];return '<tr><td class="indicator-name">'+escapeText(key.replaceAll('-',' '))+'</td><td>'+rateLabel(row)+'<br><small>'+row.applied+' / '+(row.eligible-row.declined)+' non-declined<br>'+row.declined+' declined</small></td><td>'+deltaHtml(current.comparison[scope].indicators[key])+'</td><td>'+row.verified_outcome+'</td><td>'+row.unobserved+'</td></tr>';}).join('')+'</tbody></table></div><h3 class="detail-section-title">Recent and previous completed tasks</h3><p class="fine">Recent '+view.recent_10.episodes+' tasks: '+rateLabel(view.recent_10.traits[id])+' · Previous '+view.previous_10.episodes+' tasks: '+rateLabel(view.previous_10.traits[id])+'. These windows differ from the comparison between saved reports.</p><h3 class="detail-section-title">Weekly evidence</h3>'+weeklyChart(id)+'<p class="note">Fewer than three eligible opportunities stays unmeasured. Deliberate declines are removed from the rate denominator. A rate change may reflect which tasks were reviewed, rather than a change in ability.</p>';$('trait-dialog').showModal();}
function inlineMarkdown(text){return escapeText(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdownView(text){const lines=text.split(/\r?\n/);let output='',i=0;while(i<lines.length){const line=lines[i];if(/^\|/.test(line)){const table=[];while(i<lines.length&&/^\|/.test(lines[i]))table.push(lines[i++]);const rows=table.filter(x=>!/^\|[\s:|\-]+\|$/.test(x));output+='<div class="table-scroll"><table>'+rows.map((r,j)=>'<'+(j?'tr':'thead><tr')+'>'+r.replace(/^\||\|$/g,'').split('|').map(c=>'<'+(j?'td':'th')+'>'+inlineMarkdown(c.trim())+'</'+(j?'td':'th')+'>').join('')+'</tr>'+(j?'':'</thead>')).join('')+'</table></div>';continue;}const heading=line.match(/^(#{1,3})\s+(.+)/);if(heading)output+='<h'+heading[1].length+'>'+inlineMarkdown(heading[2])+'</h'+heading[1].length+'>';else if(line.trim())output+='<p>'+inlineMarkdown(line)+'</p>';i++;}return output;}
function openReport(id){const report=data.reports.find(r=>r.id===id);$('report-dialog-title').textContent=formatDate(report.generated_at);$('report-body').innerHTML=markdownView(report.markdown);$('download-report').href='history/'+encodeURIComponent(report.id)+'.md';$('download-report').setAttribute('download',report.id+'.md');$('report-dialog').showModal();}
function renderHistory(){$('history-list').innerHTML=data.reports.map((r,i)=>'<button class="report-row" data-report="'+escapeText(r.id)+'" aria-label="Open report '+escapeText(formatDate(r.generated_at))+'"><span class="report-index">'+String(data.reports.length-i).padStart(2,'0')+'</span><span><span class="report-date">'+escapeText(formatDate(r.generated_at))+'</span><span class="report-meta">'+r.episodes+' tasks · '+r.sessions+' chats · '+(r.origin==='previous-saved-report'?'Imported previous saved status':'Skill invocation snapshot')+'</span></span><span class="report-trend">'+(r.up||r.down?'<span class="up">↑ '+r.up+'</span> / <span class="down">↓ '+r.down+'</span>':'→ No rate changes')+'</span></button>').join('');}
$('deck-nav').addEventListener('click',()=>switchView('deck'));$('reports-nav').addEventListener('click',()=>switchView('reports'));document.querySelector('.brand').addEventListener('click',()=>switchView('deck'));
$('scope-select').addEventListener('change',e=>{scope=e.target.value;render();});$('trait-search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render();});$('filters').addEventListener('click',e=>{const button=e.target.closest('[data-group]');if(button){group=button.dataset.group;renderFilters();render();}});$('deck').addEventListener('click',e=>{const card=e.target.closest('[data-trait]');if(card)openTrait(card.dataset.trait);});$('history-list').addEventListener('click',e=>{const row=e.target.closest('[data-report]');if(row)openReport(row.dataset.report);});document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>$(button.dataset.close).close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}}));
for(const option of $('scope-select').options)option.disabled=!current.scopes[option.value];$('saved-at').textContent='Saved '+formatDate(current.generated_at);$('report-nav-count').textContent=data.reports.length;renderFilters();renderHistory();render();

// Card tilt: follows the pointer, eases back on leave; off for reduced motion and touch.
(function cardTilt(){
  const calm=window.matchMedia('(prefers-reduced-motion: reduce)');
  const deck=document.getElementById('deck')||document;
  deck.addEventListener('pointermove',e=>{
    const card=e.target.closest&&e.target.closest('.trait-card');
    if(!card||calm.matches||e.pointerType==='touch')return;
    const box=card.getBoundingClientRect(),x=(e.clientX-box.left)/box.width-.5,y=(e.clientY-box.top)/box.height-.5;
    card.style.setProperty('--ry',(x*10).toFixed(2)+'deg');card.style.setProperty('--rx',(-y*8).toFixed(2)+'deg');
    card.style.setProperty('--gx',((x+.5)*100).toFixed(1)+'%');card.style.setProperty('--gy',((y+.5)*100).toFixed(1)+'%');
  });
  deck.addEventListener('pointerout',e=>{
    const card=e.target.closest&&e.target.closest('.trait-card');
    if(card&&!card.contains(e.relatedTarget)){card.style.removeProperty('--rx');card.style.removeProperty('--ry');}
  });
})();
